record Counter { n: Int64 }

fn f() -> Int64 {
    var c = Counter { n: 0 }
    let bump = fn() -> Int64 {
        c = Counter { n: c.n + 1 }
        return c.n
    }
    let _ = bump()
    return c.n
}

